public int countingValleys(int steps, String path) {
    int n = path.length();
    int[] altitude = new int[n + 1];
    for (int i = 0; i < n; i++) {
        altitude[i + 1] = altitude[i] + (path.charAt(i) == 'U' ? 1 : -1);
    }
    int valleys = 0;
    for (int i = 1; i <= n; i++) {
        if (altitude[i] == 0 && altitude[i - 1] < 0) {
            valleys++;
        }
    }
    return valleys;
}

