def countingValleys(self, steps: int, path: str) -> int:
    altitude: list[int] = [0] * (len(path) + 1)
    for i, step in enumerate(path):
        altitude[i + 1] = altitude[i] + (1 if step == 'U' else -1)
    valleys = 0
    for i in range(1, len(altitude)):
        if altitude[i] == 0 and altitude[i - 1] < 0:
            valleys += 1
    return valleys

