public int countingValleys(int steps, String path) {
    int altitude = 0;
    int valleys = 0;
    for (int i = 0; i < path.length(); i++) {
        if (path.charAt(i) == 'U') {
            altitude++;
            if (altitude == 0) {
                valleys++;
            }
        } else {
            altitude--;
        }
    }
    return valleys;
}

