def countingValleys(self, steps: int, path: str) -> int:
    altitude = 0
    valleys = 0
    for step in path:
        if step == 'U':
            altitude += 1
            if altitude == 0:
                valleys += 1
        else:
            altitude -= 1
    return valleys

